select oe1_0.id,cte01_0.mq_lineCount,cte01_0.mq_revenue,cte11_0.mq_lineCount from orders oe1_0 left join (select o1_0.id c0,count(*) c1,sum(oie1_0.unit_price) c2 from order_items oie1_0 join orders o1_0 on o1_0.id=oie1_0.order_id where oie1_0.quantity>=? and oie1_0.quantity<=? group by c0) cte01_0(mq_orderId,mq_lineCount,mq_revenue) on cte01_0.mq_orderId=oe1_0.id left join (select o2_0.id c0,count(*) c1,sum(oie2_0.unit_price) c2 from order_items oie2_0 join orders o2_0 on o2_0.id=oie2_0.order_id where oie2_0.quantity>=? and oie2_0.quantity<=? group by c0) cte11_0(mq_orderId,mq_lineCount,mq_revenue) on cte11_0.mq_orderId=oe1_0.id where oe1_0.id<=? order by 1
